const input = Array.isArray($json) ? $json : [$json];
return input.map((deal) => {
  const age = Number(deal.estimateAgeDays ?? 0);
  const value = Number(deal.estimateValue ?? 0);
  let cadence = 'wait';
  if (deal.contractSigned) cadence = 'complete';
  else if (age >= 14) cadence = 'manager-review';
  else if (age >= 3) cadence = 'follow-up-now';
  const messageTheme = value >= 15000 ? 'replacement-value-and-timing' : 'inspection-summary-and-next-step';
  return { json: { ...deal, cadence, messageTheme, nextAction: cadence === 'wait' ? 'No message today.' : cadence === 'complete' ? 'No follow-up needed.' : 'Send approved estimate or contract follow-up.' } };
});
